-- Mobile Tech Retailers: MySQL 8.0+ table setup
CREATE DATABASE IF NOT EXISTS mobiletech_analytics;
USE mobiletech_analytics;
CREATE TABLE DIM_MANUFACTURER (IdManufacturer INT PRIMARY KEY, Manufacturer_Name VARCHAR(20) NOT NULL);
CREATE TABLE DIM_MODEL (IdModel INT PRIMARY KEY, Model_Name VARCHAR(20) NOT NULL, Unit_Price DECIMAL(12,2) NOT NULL, IdManufacturer INT NOT NULL, FOREIGN KEY (IdManufacturer) REFERENCES DIM_MANUFACTURER(IdManufacturer));
CREATE TABLE DIM_CUSTOMER (IdCustomer INT PRIMARY KEY, Customer_Name VARCHAR(20), Email VARCHAR(100), Phone VARCHAR(30));
CREATE TABLE DIM_LOCATION (IdLocation INT PRIMARY KEY, ZipCode INT, Country VARCHAR(20), State VARCHAR(20), City VARCHAR(20));
CREATE TABLE DIM_DATE (`Date` DATE PRIMARY KEY, `Year` INT, Quarter VARCHAR(20), `Month` VARCHAR(20));
CREATE TABLE FACT_TRANSACTIONS (IdModel INT NOT NULL, IdCustomer INT NOT NULL, IdLocation INT NOT NULL, `Date` DATE NOT NULL, TotalPrice DECIMAL(14,2) NOT NULL, Quantity INT NOT NULL, FOREIGN KEY (IdModel) REFERENCES DIM_MODEL(IdModel), FOREIGN KEY (IdCustomer) REFERENCES DIM_CUSTOMER(IdCustomer), FOREIGN KEY (IdLocation) REFERENCES DIM_LOCATION(IdLocation), FOREIGN KEY (`Date`) REFERENCES DIM_DATE(`Date`));
